#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>
#include <float.h>
#define D 1024
#define BLOCK_N 64
#define D_TILE 128
#define WARPS_PER_BLOCK 8
#define D_PER_THREAD (D/32)
__global__ void flash_attention_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ O,
    int B, int H, int S, float scale)
{
    int bh = blockIdx.x;
    int b = bh / H;
    int h = bh % H;
    int tid = threadIdx.x;
    int warp_id = tid / 32;
    int lane = tid % 32;
    int row = blockIdx.y * WARPS_PER_BLOCK + warp_id;
    const size_t bh_off = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Kbase = K + bh_off;
    const half* Vbase = V + bh_off;
    __shared__ half sTile[BLOCK_N][D_TILE];
    int d_off = lane * D_PER_THREAD;
    half2 q_reg[D_PER_THREAD/2];
    float acc[D_PER_THREAD];
    if (row < S) {
        const half2* Qrow = reinterpret_cast<const half2*>(Q + bh_off + (size_t)row * D + d_off);
        #pragma unroll
        for (int i = 0; i < D_PER_THREAD/2; i++) {
            q_reg[i] = Qrow[i];
            acc[2*i] = 0.0f;
            acc[2*i+1] = 0.0f;
        }
    }
    float m_i = -FLT_MAX;
    float l_i = 0.0f;
    int d0_for_lane = (d_off / D_TILE) * D_TILE;
    int local_off = d_off - d0_for_lane;
    for (int n0 = 0; n0 < S; n0 += BLOCK_N) {
        int n_count = min(BLOCK_N, S - n0);
        float scores[BLOCK_N];
        #pragma unroll
        for (int j = 0; j < BLOCK_N; j++) scores[j] = 0.0f;
        // ---- Phase 1: cooperative warp-tiled Q @ K^T, staged through smem ----
        for (int d0 = 0; d0 < D; d0 += D_TILE) {
            for (int idx = tid; idx < n_count * (D_TILE / 8); idx += blockDim.x) {
                int jj = idx / (D_TILE / 8);
                int dd8 = idx % (D_TILE / 8);
                const float4* src = reinterpret_cast<const float4*>(Kbase + (size_t)(n0 + jj) * D + d0) + dd8;
                float4* dst = reinterpret_cast<float4*>(&sTile[jj][0]) + dd8;
                unsigned dst_addr = static_cast<unsigned>(__cvta_generic_to_shared(dst));
                unsigned long long src_addr = __cvta_generic_to_global(src);
                asm volatile("cp.async.ca.shared.global [%0], [%1], 16;\n" :: "r"(dst_addr), "l"(src_addr));
            }
            asm volatile("cp.async.commit_group;\n");
            asm volatile("cp.async.wait_group 0;\n");
            __syncthreads();
            if (row < S) {
                bool active = (d0 == d0_for_lane);
                for (int j = 0; j < n_count; j++) {
                    float partial = 0.0f;
                    if (active) {
                        #pragma unroll
                        for (int dd = 0; dd < D_PER_THREAD; dd += 2) {
                            half2 kv = *reinterpret_cast<const half2*>(&sTile[j][local_off + dd]);
                            partial += __half2float(q_reg[dd/2].x) * __half2float(kv.x)
                                     + __half2float(q_reg[dd/2].y) * __half2float(kv.y);
                        }
                    }
                    #pragma unroll
                    for (int offset = 16; offset > 0; offset >>= 1) {
                        partial += __shfl_xor_sync(0xffffffff, partial, offset);
                    }
                    scores[j] += partial;
                }
            }
            __syncthreads();
        }
        float p[BLOCK_N];
        if (row < S) {
            float m_new = m_i;
            for (int j = 0; j < n_count; j++) {
                scores[j] *= scale;
                if (scores[j] > m_new) m_new = scores[j];
            }
            float alpha = expf(m_i - m_new);
            l_i *= alpha;
            #pragma unroll
            for (int d = 0; d < D_PER_THREAD; d++) acc[d] *= alpha;
            for (int j = 0; j < n_count; j++) {
                p[j] = expf(scores[j] - m_new);
                l_i += p[j];
            }
            m_i = m_new;
        }
        // ---- Phase 2: P @ V, each thread owns a fixed D chunk (no reduction needed) ----
        for (int d0 = 0; d0 < D; d0 += D_TILE) {
            for (int idx = tid; idx < n_count * (D_TILE / 8); idx += blockDim.x) {
                int jj = idx / (D_TILE / 8);
                int dd8 = idx % (D_TILE / 8);
                const float4* src = reinterpret_cast<const float4*>(Vbase + (size_t)(n0 + jj) * D + d0) + dd8;
                float4* dst = reinterpret_cast<float4*>(&sTile[jj][0]) + dd8;
                unsigned dst_addr = static_cast<unsigned>(__cvta_generic_to_shared(dst));
                unsigned long long src_addr = __cvta_generic_to_global(src);
                asm volatile("cp.async.ca.shared.global [%0], [%1], 16;\n" :: "r"(dst_addr), "l"(src_addr));
            }
            asm volatile("cp.async.commit_group;\n");
            asm volatile("cp.async.wait_group 0;\n");
            __syncthreads();
            if (row < S && d0 == d0_for_lane) {
                for (int j = 0; j < n_count; j++) {
                    float pj = p[j];
                    #pragma unroll
                    for (int dd = 0; dd < D_PER_THREAD; dd++) {
                        acc[dd] += pj * __half2float(sTile[j][local_off + dd]);
                    }
                }
            }
            __syncthreads();
        }
    }
    if (row < S) {
        half* Orow = O + bh_off + (size_t)row * D + d_off;
        float inv_l = 1.0f / l_i;
        #pragma unroll
        for (int d = 0; d < D_PER_THREAD; d++) {
            Orow[d] = __float2half(acc[d] * inv_l);
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.dtype() == torch::kFloat16 && K.dtype() == torch::kFloat16 && V.dtype() == torch::kFloat16,
                "Q, K, V must be fp16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Q, K, V must be contiguous");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have matching shapes");
    int B = Q.size(0);
    int H = Q.size(1);
    int S = Q.size(2);
    int Dh = Q.size(3);
    TORCH_CHECK(Dh == D, "This kernel is specialized for head_dim = 1024");
    auto O = torch::empty_like(Q);
    float scale = 1.0f / sqrtf((float)Dh);
    dim3 grid(B * H, (S + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK);
    dim3 block(WARPS_PER_BLOCK * 32);
    flash_attention_kernel<<<grid, block>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, scale);
    return O;
}
